   1→/**
   2→ * Standalone WebSocket relay server for the thos dashboard.
   3→ *
   4→ * Runs on port 9900 alongside Next.js (started via `concurrently` in the
   5→ * `dev` script). It cannot be a Next.js API route because API routes don't
   6→ * support persistent WebSocket connections.
   7→ *
   8→ * ## Architecture
   9→ *
  10→ * Two WebSocket path families:
  11→ * - `/browser`          — the React dashboard connects here (supports multiple tabs).
  12→ * - `/claude/:agentId`  — each Claude CLI connects here (passed as `--sdk-url`).
  13→ *
  14→ * The server supports multiple concurrent agents, each tracked in the
  15→ * `agents` Map keyed by a short random ID.
  16→ *
  17→ * ## Connection flow (browser)
  18→ *
  19→ * On browser connect, the server sends two small messages:
  20→ * 1. `agent_list`  — metadata for all agents (sidebar).
  21→ * 2. `task_list`   — all tasks.
  22→ *
  23→ * Message histories are NOT sent eagerly. They are loaded lazily: the
  24→ * browser sends `{ type: "request_history", agentId }` when the user
  25→ * selects an agent, and the server responds with `message_history` for
  26→ * that single agent. This avoids sending megabytes of JSON on connect,
  27→ * which caused multi-minute loading times on mobile networks.
  28→ *
  29→ * Live messages for active agents are still broadcast to all browsers
  30→ * via `relay` messages in real time.
  31→ *
  32→ * ## Message flow (spawning)
  33→ *
  34→ * 1. Browser sends `{ type: "spawn", prompt }`.
  35→ * 2. Server creates agent entry, spawns `claude --sdk-url ws://localhost:9900/claude/<agentId>`.
  36→ * 3. CLI connects on `/claude/<agentId>`, sends `system/hook_started` then `system/hook_response`.
  37→ * 4. On `hook_response`, server forwards the pending prompt to the CLI.
  38→ * 5. CLI sends `system/init`, then `assistant` messages, then `result`.
  39→ * 6. All CLI messages are relayed to the browser as `{ type: "relay", agentId, message }`.
  40→ * 7. `control_request` messages (tool approval) are relayed to the browser;
  41→ *    the browser's `control_response` (with `agentId`) is forwarded back to the right CLI.
  42→ *
  43→ * ## Resilience features
  44→ *
  45→ * - **Server-side message history** — every relay message is stored per-agent.
  46→ * - **File persistence** — agent state + history persisted to disk, survives restarts.
  47→ * - **Multi-browser** — multiple tabs can connect simultaneously.
  48→ * - **tmux survival** — tmux sessions are NOT killed on server restart; CLI processes
  49→ *   can reconnect to the new server if they retry their WebSocket connection.
  50→ * - **Message queuing** — messages sent while CLI is disconnected are queued and flushed on reconnect.
  51→ * - **Disconnect notifications** — browser is notified of CLI disconnect/reconnect.
  52→ * - **Lazy history** — message histories loaded on demand per agent, not on connect.
  53→ */
  54→import { WebSocketServer, WebSocket } from "ws";
  55→import { execSync, spawn } from "child_process";
  56→import { randomBytes } from "crypto";
  57→import type { IncomingMessage } from "http";
  58→import { readdirSync, statSync, existsSync, writeFileSync } from "fs";
  59→import { join, dirname, basename } from "path";
  60→import { tmpdir } from "os";
  61→import type {
  62→  BrowserMessage,
  63→  ClaudeMessage,
  64→  ServerMessage,
  65→  AgentStatus,
  66→  AgentInfo,
  67→  Task,
  68→  Workspace,
  69→  DirectoryEntry,
  70→} from "../lib/types";
  71→import { SessionStore, type PersistedAgent } from "./session-store";
  72→import { TaskStore } from "./task-store";
  73→import { WorkspaceStore } from "./workspace-store";
  74→
  75→const PORT = 9900;
  76→const TMUX_SESSION_PREFIX = "thos-agent";
  77→
  78→/** Check if an IP is localhost or in the Tailscale CGNAT range (100.64.0.0/10). */
  79→function isAllowedIP(ip: string | undefined): boolean {
  80→  if (!ip) return false;
  81→  // Strip IPv6-mapped IPv4 prefix
  82→  const addr = ip.startsWith("::ffff:") ? ip.slice(7) : ip;
  83→  if (addr === "127.0.0.1" || addr === "::1" || addr === "localhost") return true;
  84→  // Tailscale CGNAT: 100.64.0.0/10 → 100.64.0.0 – 100.127.255.255
  85→  const parts = addr.split(".");
  86→  if (parts.length !== 4) return false;
  87→  const first = parseInt(parts[0], 10);
  88→  const second = parseInt(parts[1], 10);
  89→  return first === 100 && second >= 64 && second <= 127;
  90→}
  91→
  92→const wss = new WebSocketServer({
  93→  port: PORT,
  94→  verifyClient: (info: { req: { socket: { remoteAddress?: string } } }) => {
  95→    const ip = info.req.socket.remoteAddress;
  96→    const allowed = isAllowedIP(ip);
  97→    if (!allowed) console.log(`[ws] rejected connection from ${ip}`);
  98→    return allowed;
  99→  },
 100→});
 101→const store = new SessionStore();
 102→
 103→// ── Multi-agent state ──────────────────────────────────────────────────────
 104→
 105→interface AgentState {
 106→  agentId: string;
 107→  claudeSocket: WebSocket | null;
 108→  tmuxSession: string | null;
 109→  pendingPrompt: string | null;
 110→  status: AgentStatus;
 111→  label: string;
 112→  createdAt: number;
 113→  /** Captured from system/init, used in subsequent user messages. */
 114→  sessionId: string | null;
 115→  /** Workspace this agent belongs to. */
 116→  workspaceId: string | null;
 117→  /** Model name from system/init or requested at spawn time. */
 118→  model: string | null;
 119→  /** Whether this agent is pinned to the top of the sidebar. */
 120→  pinned: boolean;
 121→  /** Whether this agent is in the icebox (parked for later). */
 122→  iceboxed: boolean;
 123→  /** Stores control_request inputs keyed by request_id, for building control_responses. */
 124→  pendingControlRequests: Map<string, Record<string, unknown>>;
 125→  /** All messages sent to the browser for this agent (source of truth). */
 126→  messageHistory: ServerMessage[];
 127→  /** Messages queued while CLI is disconnected, flushed on reconnect. */
 128→  pendingMessages: string[];
 129→}
 130→
 131→const agents = new Map<string, AgentState>();
 132→const taskStore = new TaskStore();
 133→const tasks = new Map<string, Task>();
 134→const workspaceStore = new WorkspaceStore();
 135→const workspaces = new Map<string, Workspace>();
 136→
 137→/** All active browser connections (supports multiple tabs). */
 138→const browserSockets = new Set<WebSocket>();
 139→
 140→/** Per-browser workspace scope (null = show all). */
 141→const browserWorkspaceScope = new Map<WebSocket, string | null>();
 142→
 143→/** Generate a short random agent ID. */
 144→function newAgentId(): string {
 145→  return randomBytes(4).toString("hex");
 146→}
 147→
 148→// ── tmux helpers ───────────────────────────────────────────────────────────
 149→
 150→/** Return the set of currently alive tmux session names matching the thos prefix. */
 151→function listAliveTmuxSessions(): Set<string> {
 152→  try {
 153→    const output = execSync("tmux list-sessions -F '#{session_name}'", {
 154→      encoding: "utf-8",
 155→    }).trim();
 156→    if (!output) return new Set();
 157→    return new Set(output.split("\n").filter((s) => s.startsWith(TMUX_SESSION_PREFIX)));
 158→  } catch {
 159→    return new Set();
 160→  }
 161→}
 162→
 163→// ── Persistence helpers ────────────────────────────────────────────────────
 164→
 165→/** Build a PersistedAgent snapshot from live state. */
 166→function toPersistedAgent(agent: AgentState): PersistedAgent {
 167→  return {
 168→    id: agent.agentId,
 169→    state: {
 170→      agentId: agent.agentId,
 171→      status: agent.status,
 172→      tmuxSession: agent.tmuxSession,
 173→      label: agent.label,
 174→      createdAt: agent.createdAt,
 175→      sessionId: agent.sessionId,
 176→      workspaceId: agent.workspaceId,
 177→      model: agent.model,
 178→      pinned: agent.pinned || undefined,
 179→      iceboxed: agent.iceboxed || undefined,
 180→    },
 181→    messageHistory: agent.messageHistory,
 182→  };
 183→}
 184→
 185→/**
 186→ * Compact a message history by deduplicating cumulative snapshots.
 187→ * Keeps only the last version of each assistant/user message ID.
 188→ * Called on restore to shrink legacy bloated histories.
 189→ */
 190→function compactHistory(history: ServerMessage[]): ServerMessage[] {
 191→  // Build a map of msgId → last index
 192→  const lastIndex = new Map<string, number>();
 193→  for (let i = 0; i < history.length; i++) {
 194→    const id = getRelayMessageId(history[i]);
 195→    if (id) lastIndex.set(id, i);
 196→  }
 197→  // Keep only messages that are either non-deduplicable or the last occurrence
 198→  return history.filter((msg, i) => {
 199→    const id = getRelayMessageId(msg);
 200→    if (!id) return true; // non-relay or no message ID — always keep
 201→    return lastIndex.get(id) === i;
 202→  });
 203→}
 204→
 205→/** Persist agent state (debounced — use for streaming events). */
 206→function persistAgent(agent: AgentState) {
 207→  store.save(toPersistedAgent(agent));
 208→}
 209→
 210→/** Persist agent state immediately (use for critical state changes). */
 211→function persistAgentSync(agent: AgentState) {
 212→  store.saveSync(toPersistedAgent(agent));
 213→}
 214→
 215→// ── Restore from disk on startup ───────────────────────────────────────────
 216→
 217→function restoreAgents() {
 218→  const persisted = store.loadAll();
 219→  const aliveSessions = listAliveTmuxSessions();
 220→
 221→  for (const p of persisted) {
 222→    const agent: AgentState = {
 223→      agentId: p.state.agentId,
 224→      claudeSocket: null,
 225→      tmuxSession: p.state.tmuxSession,
 226→      pendingPrompt: null,
 227→      status: p.state.status,
 228→      label: p.state.label,
 229→      createdAt: p.state.createdAt,
 230→      sessionId: p.state.sessionId,
 231→      workspaceId: p.state.workspaceId ?? null,
 232→      model: p.state.model ?? null,
 233→      pinned: p.state.pinned ?? false,
 234→      iceboxed: p.state.iceboxed ?? false,
 235→      pendingControlRequests: new Map(),
 236→      messageHistory: compactHistory(p.messageHistory),
 237→      pendingMessages: [],
 238→    };
 239→
 240→    // Determine status for agents that were active when the server last ran
 241→    if (agent.status !== "done" && agent.status !== "error") {
 242→      const tmuxAlive = agent.tmuxSession ? aliveSessions.has(agent.tmuxSession) : false;
 243→      if (tmuxAlive) {
 244→        // tmux session still alive — CLI may reconnect to this server
 245→        agent.status = "disconnected";
 246→        console.log(`[restore] agent ${agent.agentId} — tmux alive, waiting for CLI reconnect`);
 247→      } else {
 248→        // tmux session gone — agent is archived
 249→        agent.status = "done";
 250→        console.log(`[restore] agent ${agent.agentId} — tmux dead, archived`);
 251→      }
 252→    }
 253→
 254→    agents.set(agent.agentId, agent);
 255→    const originalCount = p.messageHistory.length;
 256→    const compactedCount = agent.messageHistory.length;
 257→    const saved = originalCount - compactedCount;
 258→    console.log(`[restore] agent ${agent.agentId} (status=${agent.status}, ${compactedCount} messages${saved > 0 ? `, compacted from ${originalCount} (−${saved})` : ""})`);
 259→
 260→    // Persist compacted history back to disk
 261→    if (saved > 0) {
 262→      persistAgentSync(agent);
 263→    }
 264→  }
 265→  console.log(`[restore] loaded ${persisted.length} agents from disk`);
 266→}
 267→
 268→restoreAgents();
 269→
 270→// ── Task restore + helpers ────────────────────────────────────────────────
 271→
 272→function restoreTasks() {
 273→  const persisted = taskStore.loadAll();
 274→  for (const t of persisted) {
 275→    tasks.set(t.id, t);
 276→  }
 277→  console.log(`[restore] loaded ${persisted.length} tasks from disk`);
 278→}
 279→
 280→restoreTasks();
 281→
 282→// ── Workspace restore + helpers ──────────────────────────────────────────
 283→
 284→function restoreWorkspaces() {
 285→  const persisted = workspaceStore.loadAll();
 286→  for (const w of persisted) {
 287→    workspaces.set(w.id, w);
 288→  }
 289→  console.log(`[restore] loaded ${persisted.length} workspaces from disk`);
 290→}
 291→
 292→restoreWorkspaces();
 293→
 294→/** Persist all workspaces to disk (sync). */
 295→function persistWorkspaces() {
 296→  workspaceStore.saveSync(Array.from(workspaces.values()));
 297→}
 298→
 299→/** Send the full workspace list to all browsers. */
 300→function broadcastWorkspaceList() {
 301→  const payload = JSON.stringify({ type: "workspace_list", workspaces: Array.from(workspaces.values()) });
 302→  for (const ws of browserSockets) {
 303→    if (ws.readyState === WebSocket.OPEN) {
 304→      ws.send(payload);
 305→    }
 306→  }
 307→}
 308→
 309→/** Build the full task list sorted by creation time (newest first), optionally filtered by workspace. */
 310→function buildTaskList(workspaceId?: string | null): Task[] {
 311→  let list = Array.from(tasks.values());
 312→  if (workspaceId !== undefined && workspaceId !== null) {
 313→    list = list.filter((t) => t.workspaceId === workspaceId);
 314→  }
 315→  return list.sort((a, b) => b.createdAt - a.createdAt);
 316→}
 317→
 318→/** Send the full task list to all browsers (scoped per-browser workspace). */
 319→function broadcastTaskList() {
 320→  for (const ws of browserSockets) {
 321→    if (ws.readyState !== WebSocket.OPEN) continue;
 322→    const scope = browserWorkspaceScope.get(ws) ?? null;
 323→    ws.send(JSON.stringify({ type: "task_list", tasks: buildTaskList(scope) }));
 324→  }
 325→}
 326→
 327→/** Persist all tasks to disk (sync). */
 328→function persistTasks() {
 329→  taskStore.saveSync(Array.from(tasks.values()));
 330→}
 331→
 332→// ── Helpers ────────────────────────────────────────────────────────────────
 333→
 334→/** Send a JSON message to all connected browsers. */
 335→function sendToBrowser(msg: ServerMessage) {
 336→  const payload = JSON.stringify(msg);
 337→  for (const ws of browserSockets) {
 338→    if (ws.readyState === WebSocket.OPEN) {
 339→      ws.send(payload);
 340→    }
 341→  }
 342→}
 343→
 344→/** Build a snapshot of all agents for the sidebar, optionally filtered by workspace. */
 345→function buildAgentList(workspaceId?: string | null): AgentInfo[] {
 346→  let list = Array.from(agents.values());
 347→  if (workspaceId !== undefined && workspaceId !== null) {
 348→    list = list.filter((a) => a.workspaceId === workspaceId);
 349→  }
 350→  return list.map((a) => ({
 351→    agentId: a.agentId,
 352→    status: a.status,
 353→    tmuxSession: a.tmuxSession,
 354→    label: a.label,
 355→    createdAt: a.createdAt,
 356→    workspaceId: a.workspaceId,
 357→    model: a.model,
 358→    pinned: a.pinned || undefined,
 359→    iceboxed: a.iceboxed || undefined,
 360→  }));
 361→}
 362→
 363→/** Send the full agent list to all browsers (scoped per-browser workspace). */
 364→function broadcastAgentList() {
 365→  for (const ws of browserSockets) {
 366→    if (ws.readyState !== WebSocket.OPEN) continue;
 367→    const scope = browserWorkspaceScope.get(ws) ?? null;
 368→    ws.send(JSON.stringify({ type: "agent_list", agents: buildAgentList(scope) }));
 369→  }
 370→}
 371→
 372→/** Update an agent's status, notify browsers, broadcast list, and persist. */
 373→function setAgentStatus(agentId: string, status: AgentStatus) {
 374→  const agent = agents.get(agentId);
 375→  if (!agent) return;
 376→  agent.status = status;
 377→  sendToBrowser({ type: "status", agentId, status });
 378→  broadcastAgentList();
 379→  persistAgentSync(agent);
 380→}
 381→
 382→/**
 383→ * Extract a stable dedup key from a relay message, if present.
 384→ *
 385→ * Claude NDJSON sends cumulative snapshots for two message types:
 386→ * - `assistant` — keyed by `message.id` (e.g. `msg_01VE1P7c...`)
 387→ * - `user` (tool_result) — keyed by top-level `uuid` (e.g. `b217b852-...`)
 388→ *
 389→ * Additionally, one-per-session messages are deduplicated by session_id:
 390→ * - `system/init` — keyed by `init:<session_id>`
 391→ * - `result` — keyed by `result:<session_id>`
 392→ *
 393→ * We deduplicate by replacing the previous snapshot in `messageHistory`
 394→ * instead of appending, reducing storage from O(n²) to O(n).
 395→ */
 396→function getRelayMessageId(msg: ServerMessage): string | null {
 397→  if (msg.type !== "relay") return null;
 398→  const inner = msg.message;
 399→  if (inner.type === "assistant") {
 400→    return (inner as { message?: { id?: string } }).message?.id ?? null;
 401→  }
 402→  if (inner.type === "user") {
 403→    return (inner as { uuid?: string }).uuid ?? null;
 404→  }
 405→  // Dedup system/init and result by session_id so they don't stack on reload
 406→  if (inner.type === "system" && (inner as { subtype?: string }).subtype === "init") {
 407→    const sid = (inner as { session_id?: string }).session_id;
 408→    return sid ? `init:${sid}` : null;
 409→  }
 410→  if (inner.type === "result") {
 411→    const sid = (inner as { session_id?: string }).session_id;
 412→    return sid ? `result:${sid}` : null;
 413→  }
 414→  return null;
 415→}
 416→
 417→/**
 418→ * Record a message in the agent's history and send to all browsers.
 419→ *
 420→ * For cumulative snapshot messages (assistant, user/tool_result), replaces the
 421→ * previous snapshot with the same message ID instead of appending. This keeps
 422→ * only the final version of each message, dramatically reducing file sizes
 423→ * (e.g. 38 MB → ~1 MB for a typical session).
 424→ */
 425→function recordAndSend(agentId: string, msg: ServerMessage) {
 426→  const agent = agents.get(agentId);
 427→  if (agent) {
 428→    const msgId = getRelayMessageId(msg);
 429→    if (msgId) {
 430→      // Replace previous snapshot with same message ID (search from end for speed)
 431→      let replaced = false;
 432→      for (let i = agent.messageHistory.length - 1; i >= 0; i--) {
 433→        if (getRelayMessageId(agent.messageHistory[i]) === msgId) {
 434→          agent.messageHistory[i] = msg;
 435→          replaced = true;
 436→          break;
 437→        }
 438→      }
 439→      if (!replaced) {
 440→        agent.messageHistory.push(msg);
 441→      }
 442→    } else {
 443→      agent.messageHistory.push(msg);
 444→    }
 445→    persistAgent(agent); // debounced — streaming messages come fast
 446→  }
 447→  sendToBrowser(msg);
 448→}
 449→
 450→// ── Agent lifecycle ────────────────────────────────────────────────────────
 451→
 452→/**
 453→ * Stop a running agent by killing its tmux session and closing the CLI socket.
 454→ * The agent remains in the Map (status set to "done") so it can be viewed/deleted later.
 455→ */
 456→function stopAgent(agentId: string) {
 457→  const agent = agents.get(agentId);
 458→  if (!agent) return;
 459→
 460→  if (agent.tmuxSession) {
 461→    try {
 462→      execSync(`tmux kill-session -t ${agent.tmuxSession}`, { stdio: "ignore" });
 463→      console.log(`[tmux] killed session ${agent.tmuxSession}`);
 464→    } catch {
 465→      // Session may already be dead
 466→    }
 467→  }
 468→  if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
 469→    agent.claudeSocket.close();
 470→  }
 471→  agent.claudeSocket = null;
 472→  setAgentStatus(agentId, "done");
 473→}
 474→
 475→/**
 476→ * Permanently delete an agent: stop it, remove from Map, remove from disk.
 477→ */
 478→function deleteAgent(agentId: string) {
 479→  const agent = agents.get(agentId);
 480→  if (!agent) return;
 481→
 482→  if (agent.tmuxSession) {
 483→    try {
 484→      execSync(`tmux kill-session -t ${agent.tmuxSession}`, { stdio: "ignore" });
 485→    } catch {}
 486→  }
 487→  if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
 488→    agent.claudeSocket.close();
 489→  }
 490→  agents.delete(agentId);
 491→  store.remove(agentId);
 492→  broadcastAgentList();
 493→}
 494→
 495→/**
 496→ * Spawn a new Claude CLI process inside a tmux session.
 497→ *
 498→ * Creates a new agent entry, spawns the CLI with `--sdk-url` pointing to
 499→ * `/claude/<agentId>`, and sends a `spawned` message to the browser.
 500→ * If `workspaceId` is provided, the tmux session starts in that workspace's cwd.
 501→ */
 502→function spawnClaude(prompt: string, workspaceId?: string | null, model?: string | null, systemPrompt?: string | null): string {
 503→  const agentId = newAgentId();
 504→  const sessionName = `${TMUX_SESSION_PREFIX}-${agentId}`;
 505→  const label = prompt.length > 60 ? prompt.slice(0, 57) + "..." : prompt;
 506→
 507→  const agent: AgentState = {
 508→    agentId,
 509→    claudeSocket: null,
 510→    tmuxSession: null,
 511→    pendingPrompt: prompt,
 512→    status: "spawning",
 513→    label,
 514→    createdAt: Date.now(),
 515→    sessionId: null,
 516→    workspaceId: workspaceId ?? null,
 517→    model: model ?? null,
 518→    pinned: false,
 519→    iceboxed: false,
 520→    pendingControlRequests: new Map(),
 521→    messageHistory: [],
 522→    pendingMessages: [],
 523→  };
 524→  agents.set(agentId, agent);
 525→
 526→  // Notify browsers
 527→  sendToBrowser({ type: "spawned", agentId });
 528→  broadcastAgentList();
 529→  persistAgentSync(agent);
 530→
 531→  // Build the claude command with CLAUDECODE unset to bypass nesting protection.
 532→  // tmux new-session runs detached (-d) so spawn() returns immediately.
 533→  const modelFlag = model ? ` --model ${model}` : "";
 534→  let systemPromptFlag = "";
 535→  if (systemPrompt) {
 536→    // Write system prompt to a temp file to avoid shell escaping issues
 537→    const spFile = join(tmpdir(), `thos-sp-${agentId}`);
 538→    writeFileSync(spFile, systemPrompt, "utf-8");
 539→    systemPromptFlag = ` --append-system-prompt "$(cat ${spFile})"`;
 540→  }
 541→  const claudeCmd = `unset CLAUDECODE; exec claude --dangerously-skip-permissions${modelFlag}${systemPromptFlag} --sdk-url ws://localhost:${PORT}/claude/${agentId}`;
 542→
 543→  // If the agent belongs to a workspace, start tmux in that workspace's cwd
 544→  const workspace = workspaceId ? workspaces.get(workspaceId) : null;
 545→  const tmuxArgs = ["new-session", "-d", "-s", sessionName];
 546→  if (workspace) {
 547→    tmuxArgs.push("-c", workspace.cwd);
 548→  }
 549→  tmuxArgs.push("bash", "-c", claudeCmd);
 550→
 551→  const tmux = spawn("tmux", tmuxArgs, {
 552→    stdio: "ignore",
 553→  });
 554→
 555→  tmux.on("error", (err) => {
 556→    console.error("[tmux spawn error]", err);
 557→    setAgentStatus(agentId, "error");
 558→    recordAndSend(agentId, { type: "error", agentId, error: `tmux error: ${err.message}` });
 559→  });
 560→
 561→  tmux.on("exit", (code) => {
 562→    if (code !== 0) {
 563→      console.error(`[tmux] new-session exited with code ${code}`);
 564→      setAgentStatus(agentId, "error");
 565→      recordAndSend(agentId, { type: "error", agentId, error: `tmux exited with code ${code}` });
 566→      return;
 567→    }
 568→    console.log(`[tmux] session ${sessionName} created — attach with: tmux attach -t ${sessionName}`);
 569→    agent.tmuxSession = sessionName;
 570→    broadcastAgentList();
 571→    persistAgentSync(agent);
 572→  });
 573→
 574→  return agentId;
 575→}
 576→
 577→// ── Message handlers ───────────────────────────────────────────────────────
 578→
 579→/**
 580→ * Process an incoming NDJSON message from a specific Claude CLI.
 581→ *
 582→ * Status flow matches the Companion protocol:
 583→ * - hook_response → send pending prompt → "thinking"
 584→ * - system/init   → "connected" + capture session_id
 585→ * - assistant      → "thinking"
 586→ * - result         → "connected" (CLI stays alive for multi-turn)
 587→ * - CLI disconnect → "done" (handled in connection close handler)
 588→ */
 589→function handleClaudeMessage(agentId: string, raw: string) {
 590→  const agent = agents.get(agentId);
 591→  if (!agent) return;
 592→
 593→  let msg: ClaudeMessage;
 594→  try {
 595→    msg = JSON.parse(raw);
 596→  } catch {
 597→    console.error(`[claude:${agentId}] invalid JSON:`, raw);
 598→    return;
 599→  }
 600→
 601→  // Silently ignore keep_alive messages
 602→  if (msg.type === "keep_alive") return;
 603→
 604→  console.log(`[claude:${agentId} →]`, msg.type, (msg as { subtype?: string }).subtype ?? "");
 605→
 606→  // After hook_response, send the pending prompt
 607→  if (
 608→    msg.type === "system" &&
 609→    (msg as { subtype?: string }).subtype === "hook_response" &&
 610→    agent.pendingPrompt &&
 611→    agent.claudeSocket?.readyState === WebSocket.OPEN
 612→  ) {
 613→    const promptContent = agent.pendingPrompt;
 614→    const userMsg = JSON.stringify({
 615→      type: "user",
 616→      message: { role: "user", content: promptContent },
 617→      parent_tool_use_id: null,
 618→      session_id: agent.sessionId ?? "",
 619→    });
 620→    console.log(`[server → claude:${agentId}]`, userMsg);
 621→    agent.claudeSocket.send(userMsg + "\n");
 622→    agent.pendingPrompt = null;
 623→    setAgentStatus(agentId, "thinking");
 624→
 625→    // Record the initial user message so it appears in chat and persists across reloads
 626→    recordAndSend(agentId, {
 627→      type: "relay",
 628→      agentId,
 629→      message: { type: "user", message: { role: "user", content: promptContent } } as ClaudeMessage,
 630→    });
 631→  }
 632→
 633→  // Track status based on message type
 634→  if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
 635→    // Capture session_id and model for subsequent user messages
 636→    agent.sessionId = (msg as { session_id?: string }).session_id ?? null;
 637→    agent.model = (msg as { model?: string }).model ?? agent.model;
 638→    setAgentStatus(agentId, "connected");
 639→  } else if (msg.type === "assistant") {
 640→    setAgentStatus(agentId, "thinking");
 641→  } else if (msg.type === "result") {
 642→    // CLI stays alive after result — ready for the next turn.
 643→    // Status only goes to "done" when the CLI WebSocket actually closes.
 644→    setAgentStatus(agentId, "connected");
 645→  }
 646→
 647→  // Store control_request inputs for building proper responses later
 648→  if (msg.type === "control_request") {
 649→    const cr = msg as { request_id?: string; request?: { input?: Record<string, unknown> } };
 650→    if (cr.request_id && cr.request?.input) {
 651→      agent.pendingControlRequests.set(cr.request_id, cr.request.input);
 652→    }
 653→  }
 654→
 655→  // Record in history and relay to browsers
 656→  recordAndSend(agentId, { type: "relay", agentId, message: msg });
 657→}
 658→
 659→/**
 660→ * Process an incoming JSON message from the browser.
 661→ * - `spawn`: create a new agent (does NOT kill others).
 662→ * - `send_message`: forward a follow-up user message to the specified agent.
 663→ * - `control_response`: forward a tool allow/deny decision to the specified agent.
 664→ * - `kill_agent`: stop the CLI and tmux session.
 665→ * - `delete_agent`: permanently remove an agent.
 666→ * - `rename_agent`: update an agent's label.
 667→ * - `clear_history`: wipe an agent's message history.
 668→ * - `request_history`: send message history for a single agent (lazy loading).
 669→ * - `create_task` / `update_task` / `delete_task` / `delegate_task`: task CRUD.
 670→ */
 671→function handleBrowserMessage(raw: string, senderWs: WebSocket) {
 672→  let msg: BrowserMessage;
 673→  try {
 674→    msg = JSON.parse(raw);
 675→  } catch {
 676→    console.error("[browser] invalid JSON:", raw);
 677→    return;
 678→  }
 679→
 680→  console.log("[browser →]", msg.type);
 681→
 682→  switch (msg.type) {
 683→    case "spawn": {
 684→      const scope = browserWorkspaceScope.get(senderWs) ?? msg.workspaceId ?? null;
 685→      spawnClaude(msg.prompt, scope, msg.model, msg.systemPrompt);
 686→      break;
 687→    }
 688→
 689→    case "send_message": {
 690→      const agent = agents.get(msg.agentId);
 691→      if (!agent) {
 692→        sendToBrowser({ type: "error", agentId: msg.agentId, error: "Unknown agent" });
 693→        break;
 694→      }
 695→
 696→      // Record the user message in history so it persists across reloads.
 697→      // Do NOT broadcast — the sending browser already has it optimistically,
 698→      // and other browsers will get it when they request_history.
 699→      agent.messageHistory.push({
 700→        type: "relay",
 701→        agentId: msg.agentId,
 702→        message: { type: "user", message: { role: "user", content: msg.content } },
 703→      } as ServerMessage);
 704→      persistAgent(agent);
 705→
 706→      if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
 707→        const userMsg = JSON.stringify({
 708→          type: "user",
 709→          message: { role: "user", content: msg.content },
 710→          parent_tool_use_id: null,
 711→          session_id: agent.sessionId ?? "",
 712→        });
 713→        agent.claudeSocket.send(userMsg + "\n");
 714→        setAgentStatus(msg.agentId, "thinking");
 715→      } else {
 716→        // Queue message for delivery when CLI reconnects
 717→        const userMsg = JSON.stringify({
 718→          type: "user",
 719→          message: { role: "user", content: msg.content },
 720→          parent_tool_use_id: null,
 721→          session_id: agent.sessionId ?? "",
 722→        });
 723→        agent.pendingMessages.push(userMsg);
 724→        console.log(`[queue] queued message for agent ${msg.agentId} (${agent.pendingMessages.length} pending)`);
 725→        persistAgentSync(agent);
 726→      }
 727→      break;
 728→    }
 729→
 730→    case "control_response": {
 731→      const agent = agents.get(msg.agentId);
 732→      if (agent?.claudeSocket?.readyState === WebSocket.OPEN) {
 733→        // Retrieve the original tool input to include as updatedInput (required by protocol)
 734→        const originalInput = agent.pendingControlRequests.get(msg.request_id) ?? {};
 735→        agent.pendingControlRequests.delete(msg.request_id);
 736→
 737→        // If the browser sent answers (from AskUserQuestion), merge them into the input
 738→        const answers = (msg as { answers?: Record<string, string> }).answers;
 739→        const updatedInput = answers
 740→          ? { ...originalInput, answers }
 741→          : originalInput;
 742→
 743→        const response = JSON.stringify({
 744→          type: "control_response",
 745→          response: {
 746→            subtype: "success",
 747→            request_id: msg.request_id,
 748→            response: msg.allow
 749→              ? { behavior: "allow", updatedInput }
 750→              : { behavior: "deny", message: "Denied by user" },
 751→          },
 752→        });
 753→        agent.claudeSocket.send(response + "\n");
 754→      }
 755→      break;
 756→    }
 757→
 758→    case "kill_agent":
 759→      stopAgent(msg.agentId);
 760→      break;
 761→
 762→    case "delete_agent":
 763→      deleteAgent(msg.agentId);
 764→      break;
 765→
 766→    case "rename_agent": {
 767→      const agent = agents.get(msg.agentId);
 768→      if (!agent) break;
 769→      agent.label = msg.label;
 770→      broadcastAgentList();
 771→      persistAgentSync(agent);
 772→      break;
 773→    }
 774→
 775→    case "clear_history": {
 776→      const agent = agents.get(msg.agentId);
 777→      if (!agent) break;
 778→      agent.messageHistory = [];
 779→      persistAgentSync(agent);
 780→      sendToBrowser({ type: "history_cleared", agentId: msg.agentId });
 781→      break;
 782→    }
 783→
 784→    case "pin_agent": {
 785→      const agent = agents.get(msg.agentId);
 786→      if (!agent) break;
 787→      agent.pinned = msg.pinned;
 788→      broadcastAgentList();
 789→      persistAgentSync(agent);
 790→      break;
 791→    }
 792→
 793→    case "icebox_agent": {
 794→      const agent = agents.get(msg.agentId);
 795→      if (!agent) break;
 796→      agent.iceboxed = msg.iceboxed;
 797→      broadcastAgentList();
 798→      persistAgentSync(agent);
 799→      break;
 800→    }
 801→
 802→    case "move_agent": {
 803→      const agent = agents.get(msg.agentId);
 804→      if (!agent) break;
 805→      agent.workspaceId = msg.workspaceId;
 806→      broadcastAgentList();
 807→      persistAgentSync(agent);
 808→      break;
 809→    }
 810→
 811→    case "request_history": {
 812→      console.log(`[browser] request_history for ${msg.agentId}`);
 813→      sendHistoryToSocket(senderWs, msg.agentId);
 814→      break;
 815→    }
 816→
 817→    case "create_task": {
 818→      const taskId = randomBytes(4).toString("hex");
 819→      const task: Task = {
 820→        id: taskId,
 821→        title: msg.title,
 822→        description: msg.description,
 823→        status: "todo",
 824→        priority: msg.priority,
 825→        agentId: null,
 826→        workspaceId: browserWorkspaceScope.get(senderWs) ?? null,
 827→        createdAt: Date.now(),
 828→        updatedAt: Date.now(),
 829→      };
 830→      tasks.set(taskId, task);
 831→      persistTasks();
 832→      broadcastTaskList();
 833→      break;
 834→    }
 835→
 836→    case "update_task": {
 837→      const task = tasks.get(msg.taskId);
 838→      if (!task) break;
 839→      Object.assign(task, msg.updates, { updatedAt: Date.now() });
 840→      persistTasks();
 841→      broadcastTaskList();
 842→
 843→      // Archive the linked agent when a task is marked as done
 844→      if (task.status === "done" && task.agentId) {
 845→        const linkedAgent = agents.get(task.agentId);
 846→        if (linkedAgent && linkedAgent.status !== "done") {
 847→          stopAgent(task.agentId);
 848→        }
 849→      }
 850→      break;
 851→    }
 852→
 853→    case "delete_task": {
 854→      tasks.delete(msg.taskId);
 855→      persistTasks();
 856→      broadcastTaskList();
 857→      break;
 858→    }
 859→
 860→    case "delegate_task": {
 861→      const task = tasks.get(msg.taskId);
 862→      if (!task) break;
 863→      const prompt = `Task: ${task.title}\n\n${task.description}`;
 864→      const agentId = spawnClaude(prompt, task.workspaceId);
 865→      task.agentId = agentId;
 866→      task.status = "in-progress";
 867→      task.updatedAt = Date.now();
 868→      persistTasks();
 869→      broadcastTaskList();
 870→      break;
 871→    }
 872→
 873→    // ── Workspace messages ──────────────────────────────────────────────
 874→
 875→    case "set_workspace": {
 876→      browserWorkspaceScope.set(senderWs, msg.workspaceId);
 877→      // Re-send scoped agent list and task list to this browser
 878→      const scope = msg.workspaceId;
 879→      senderWs.send(JSON.stringify({ type: "agent_list", agents: buildAgentList(scope) }));
 880→      senderWs.send(JSON.stringify({ type: "task_list", tasks: buildTaskList(scope) }));
 881→      break;
 882→    }
 883→
 884→    case "create_workspace": {
 885→      const id = randomBytes(4).toString("hex");
 886→      const workspace: Workspace = {
 887→        id,
 888→        name: msg.name,
 889→        cwd: msg.cwd,
 890→        createdAt: Date.now(),
 891→      };
 892→      workspaces.set(id, workspace);
 893→      persistWorkspaces();
 894→      broadcastWorkspaceList();
 895→      break;
 896→    }
 897→
 898→    case "rename_workspace": {
 899→      const workspace = workspaces.get(msg.workspaceId);
 900→      if (!workspace) break;
 901→      workspace.name = msg.name;
 902→      persistWorkspaces();
 903→      broadcastWorkspaceList();
 904→      break;
 905→    }
 906→
 907→    case "delete_workspace": {
 908→      workspaces.delete(msg.workspaceId);
 909→      // Unlink agents and tasks from the deleted workspace
 910→      for (const agent of agents.values()) {
 911→        if (agent.workspaceId === msg.workspaceId) {
 912→          agent.workspaceId = null;
 913→          persistAgentSync(agent);
 914→        }
 915→      }
 916→      for (const task of tasks.values()) {
 917→        if (task.workspaceId === msg.workspaceId) {
 918→          task.workspaceId = null;
 919→        }
 920→      }
 921→      persistTasks();
 922→      persistWorkspaces();
 923→      broadcastWorkspaceList();
 924→      broadcastAgentList();
 925→      broadcastTaskList();
 926→      break;
 927→    }
 928→
 929→    case "browse_directory": {
 930→      const dirPath = msg.path;
 931→      try {
 932→        if (!existsSync(dirPath)) {
 933→          senderWs.send(JSON.stringify({ type: "directory_listing", path: dirPath, entries: [] }));
 934→          break;
 935→        }
 936→        const entries: DirectoryEntry[] = [];
 937→        // Add parent directory entry
 938→        const parent = dirname(dirPath);
 939→        if (parent !== dirPath) {
 940→          entries.push({ name: "..", path: parent });
 941→        }
 942→        // List subdirectories only
 943→        const items = readdirSync(dirPath);
 944→        for (const item of items) {
 945→          if (item.startsWith(".")) continue; // skip dotfiles
 946→          const fullPath = join(dirPath, item);
 947→          try {
 948→            const stat = statSync(fullPath);
 949→            if (stat.isDirectory()) {
 950→              entries.push({ name: item, path: fullPath });
 951→            }
 952→          } catch {
 953→            // skip inaccessible entries
 954→          }
 955→        }
 956→        // Sort: ".." first, then alphabetical
 957→        entries.sort((a, b) => {
 958→          if (a.name === "..") return -1;
 959→          if (b.name === "..") return 1;
 960→          return a.name.localeCompare(b.name);
 961→        });
 962→        senderWs.send(JSON.stringify({ type: "directory_listing", path: dirPath, entries }));
 963→      } catch (err) {
 964→        console.error(`[browse_directory] error reading ${dirPath}:`, err);
 965→        senderWs.send(JSON.stringify({ type: "directory_listing", path: dirPath, entries: [] }));
 966→      }
 967→      break;
 968→    }
 969→  }
 970→}
 971→
 972→// ── Send message history to a single browser socket ────────────────────────
 973→
 974→/** Send initial state (workspaces, agent list, tasks) to a newly connected browser. */
 975→function sendFullStateToSocket(ws: WebSocket) {
 976→  if (ws.readyState !== WebSocket.OPEN) return;
 977→
 978→  // Workspace list
 979→  ws.send(JSON.stringify({ type: "workspace_list", workspaces: Array.from(workspaces.values()) }));
 980→
 981→  // Agent list (sidebar metadata) — scoped if browser has a workspace set
 982→  const scope = browserWorkspaceScope.get(ws) ?? null;
 983→  ws.send(JSON.stringify({ type: "agent_list", agents: buildAgentList(scope) }));
 984→
 985→  // Task list — scoped if browser has a workspace set
 986→  ws.send(JSON.stringify({ type: "task_list", tasks: buildTaskList(scope) }));
 987→}
 988→
 989→/** Send message history for a single agent to a specific browser socket. */
 990→function sendHistoryToSocket(ws: WebSocket, agentId: string) {
 991→  const agent = agents.get(agentId);
 992→  if (!agent || ws.readyState !== WebSocket.OPEN) return;
 993→  ws.send(
 994→    JSON.stringify({
 995→      type: "message_history",
 996→      agentId: agent.agentId,
 997→      messages: agent.messageHistory,
 998→    })
 999→  );
1000→}
1001→
1002→// ── Connection handler — route by URL path ────────────────────────────────
1003→wss.on("connection", (ws: WebSocket, req: IncomingMessage) => {
1004→  const path = req.url ?? "/";
1005→  console.log(`[ws connected] path=${path}`);
1006→
1007→  if (path === "/browser") {
1008→    // Send full state BEFORE adding to browserSockets so that live
1009→    // relay broadcasts don't interleave with the history replay.
1010→    sendFullStateToSocket(ws);
1011→    browserSockets.add(ws);
1012→
1013→    ws.on("message", (data) => {
1014→      handleBrowserMessage(data.toString(), ws);
1015→    });
1016→
1017→    ws.on("close", () => {
1018→      console.log("[browser disconnected]");
1019→      browserSockets.delete(ws);
1020→      browserWorkspaceScope.delete(ws);
1021→      // Do NOT kill agents — keep them alive for reconnect
1022→    });
1023→  } else if (path.startsWith("/claude/")) {
1024→    // Parse agentId from /claude/<agentId>
1025→    const agentId = path.slice("/claude/".length);
1026→    const agent = agents.get(agentId);
1027→
1028→    if (!agent) {
1029→      console.log(`[ws] unknown agentId: ${agentId}, closing`);
1030→      ws.close();
1031→      return;
1032→    }
1033→
1034→    agent.claudeSocket = ws;
1035→    console.log(`[claude:${agentId} CLI connected via WebSocket]`);
1036→
1037→    // Notify browsers that CLI is connected
1038→    sendToBrowser({ type: "cli_connected", agentId });
1039→
1040→    // Flush any pending messages queued while CLI was disconnected
1041→    if (agent.pendingMessages.length > 0) {
1042→      console.log(`[flush] sending ${agent.pendingMessages.length} queued messages to agent ${agentId}`);
1043→      for (const queued of agent.pendingMessages) {
1044→        ws.send(queued + "\n");
1045→      }
1046→      agent.pendingMessages = [];
1047→      persistAgentSync(agent);
1048→    }
1049→
1050→    // Send the pending prompt immediately — CLI 2.1.42+ waits for the
1051→    // server to send the first user message rather than emitting
1052→    // hook_started/hook_response on connect.
1053→    if (agent.pendingPrompt && ws.readyState === WebSocket.OPEN) {
1054→      const promptContent = agent.pendingPrompt;
1055→      const userMsg = JSON.stringify({
1056→        type: "user",
1057→        message: { role: "user", content: promptContent },
1058→        parent_tool_use_id: null,
1059→        session_id: agent.sessionId ?? "",
1060→      });
1061→      console.log(`[server → claude:${agentId}] sending pending prompt`);
1062→      ws.send(userMsg + "\n");
1063→      agent.pendingPrompt = null;
1064→      setAgentStatus(agentId, "thinking");
1065→
1066→      // Record the initial user message so it appears in chat and persists across reloads
1067→      recordAndSend(agentId, {
1068→        type: "relay",
1069→        agentId,
1070→        message: { type: "user", message: { role: "user", content: promptContent } } as ClaudeMessage,
1071→      });
1072→    }
1073→
1074→    ws.on("message", (data) => {
1075→      handleClaudeMessage(agentId, data.toString());
1076→    });
1077→
1078→    ws.on("close", () => {
1079→      console.log(`[claude:${agentId} CLI disconnected]`);
1080→      if (agent.claudeSocket === ws) {
1081→        agent.claudeSocket = null;
1082→        if (agent.status !== "error") {
1083→          setAgentStatus(agentId, "done");
1084→          sendToBrowser({ type: "cli_disconnected", agentId });
1085→
1086→          // Auto-complete any task linked to this agent
1087→          for (const task of tasks.values()) {
1088→            if (task.agentId === agentId && task.status !== "done") {
1089→              task.status = "done";
1090→              task.updatedAt = Date.now();
1091→              persistTasks();
1092→              broadcastTaskList();
1093→              break;
1094→            }
1095→          }
1096→        }
1097→      }
1098→    });
1099→  } else {
1100→    console.log(`[ws] unknown path: ${path}, closing`);
1101→    ws.close();
1102→  }
1103→});
1104→
1105→// ── Graceful shutdown ─────────────────────────────────────────────────────
1106→
1107→function shutdown() {
1108→  console.log("[ws server] shutting down...");
1109→
1110→  // Persist all agents synchronously before exit — do NOT kill tmux sessions
1111→  // so CLI processes can reconnect if the server restarts.
1112→  const allPersisted = Array.from(agents.values()).map(toPersistedAgent);
1113→  store.flushAll(allPersisted);
1114→  console.log(`[ws server] saved ${allPersisted.length} agents to disk (tmux sessions preserved)`);
1115→
1116→  taskStore.flush(Array.from(tasks.values()));
1117→  console.log(`[ws server] saved ${tasks.size} tasks to disk`);
1118→
1119→  persistWorkspaces();
1120→  console.log(`[ws server] saved ${workspaces.size} workspaces to disk`);
1121→
1122→  wss.close();
1123→  process.exit(0);
1124→}
1125→
1126→process.on("SIGTERM", shutdown);
1127→process.on("SIGINT", shutdown);
1128→
1129→console.log(`[ws server] listening on port ${PORT}`);
