  1→"use client";
  2→
  3→/**
  4→ * Dashboard route (`/dashboard`).
  5→ *
  6→ * Orchestrates the multi-agent WebSocket hook, sidebar, chat panel, and
  7→ * task panel. Clicking "+" or selecting "New Agent" sets `activeAgentId`
  8→ * to `null`, which shows the spawn input. On spawn, the server responds
  9→ * with `spawned` and the hook auto-selects the new agent.
 10→ *
 11→ * ## Loading states
 12→ *
 13→ * Two loading flags from the hook control the UI:
 14→ * - `initialLoadDone` — false until the first `agent_list` arrives from
 15→ *   the server. While false, the sidebar shows skeleton rows.
 16→ * - `historyLoading` — true when the active agent's message history has
 17→ *   not been fetched yet (lazy loading). The chat shows a "Loading
 18→ *   messages..." indicator until the server responds.
 19→ *
 20→ * Sidebar uses `!initialLoadDone`, chat uses `!initialLoadDone || historyLoading`.
 21→ */
 22→
 23→import { Suspense, useCallback, useEffect, useRef, useState } from "react";
 24→import { useSearchParams, useRouter } from "next/navigation";
 25→import { toast } from "sonner";
 26→import { useWebSocket } from "@/hooks/use-websocket";
 27→import {
 28→  initNotifications,
 29→  isNotificationsEnabled,
 30→  setNotificationsEnabled,
 31→  requestPermission,
 32→} from "@/lib/notifications";
 33→import { AgentSidebar } from "@/components/dashboard/agent-sidebar";
 34→import { AgentWorld } from "@/components/dashboard/agent-world";
 35→import { Chat } from "@/components/dashboard/chat";
 36→import { TaskPanel, type TaskViewMode } from "@/components/dashboard/kanban-board";
 37→import { DiffsPanel } from "@/components/dashboard/diffs-panel";
 38→import { FolderBrowser } from "@/components/dashboard/folder-browser";
 39→import { SettingsMenu, getDefaultPrompt, setDefaultPrompt } from "@/components/dashboard/settings-menu";
 40→import { Toaster } from "@/components/ui/sonner";
 41→import { TooltipProvider } from "@/components/ui/tooltip";
 42→import { cn } from "@/lib/utils";
 43→
 44→export default function DashboardPage() {
 45→  return (
 46→    <Suspense>
 47→      <DashboardContent />
 48→    </Suspense>
 49→  );
 50→}
 51→
 52→function DashboardContent() {
 53→  const searchParams = useSearchParams();
 54→  const router = useRouter();
 55→  const agentIdFromUrl = searchParams.get("agent") || null;
 56→
 57→  const navigateToAgent = useCallback(
 58→    (agentId: string | null) => {
 59→      if (agentId) {
 60→        router.replace(`/dashboard?agent=${agentId}`, { scroll: false });
 61→      } else {
 62→        router.replace("/dashboard", { scroll: false });
 63→      }
 64→    },
 65→    [router]
 66→  );
 67→
 68→  const {
 69→    connected,
 70→    initialLoadDone,
 71→    historyLoading,
 72→    agents,
 73→    agentOrder,
 74→    activeAgentId,
 75→    activeStatus,
 76→    activeMessages,
 77→    activeRawMessages,
 78→    activeModel,
 79→    spawnAgent,
 80→    sendMessage,
 81→    respondToControl,
 82→    respondToUserQuestion,
 83→    killAgent,
 84→    deleteAgent,
 85→    renameAgent,
 86→    clearHistory,
 87→    pinAgent,
 88→    iceboxAgent,
 89→    moveAgent,
 90→    tasks,
 91→    createTask,
 92→    updateTask,
 93→    deleteTask,
 94→    delegateTask,
 95→    workspaces,
 96→    activeWorkspaceId,
 97→    setActiveWorkspaceId,
 98→    createWorkspace,
 99→    renameWorkspace,
100→    deleteWorkspace,
101→    browseDirectory,
102→    directoryListing,
103→    notifications,
104→    clearNotifications,
105→    dismissNotification,
106→    markNotificationRead,
107→    testNotification,
108→  } = useWebSocket({ activeAgentId: agentIdFromUrl, onNavigateToAgent: navigateToAgent });
109→
110→  const [taskView, setTaskView] = useState<"hidden" | TaskViewMode>("hidden");
111→  const [showWorld, setShowWorld] = useState(false);
112→  const [showDiffs, setShowDiffs] = useState(false);
113→  const [sidebarOpen, setSidebarOpen] = useState(false);
114→  const [folderBrowserOpen, setFolderBrowserOpen] = useState(false);
115→  const [settingsOpen, setSettingsOpen] = useState(false);
116→  const [selectedModel, setSelectedModel] = useState("");
117→  const [notificationsEnabled, setNotificationsEnabledState] = useState(false);
118→  const [defaultSystemPrompt, setDefaultSystemPrompt] = useState("");
119→
120→  // Initialize notifications on mount
121→  useEffect(() => {
122→    initNotifications();
123→    setNotificationsEnabledState(isNotificationsEnabled());
124→    setDefaultSystemPrompt(getDefaultPrompt());
125→  }, []);
126→
127→  const handleToggleNotifications = async () => {
128→    if (!notificationsEnabled) {
129→      // Enabling: request permission first if needed
130→      const granted = await requestPermission();
131→      if (!granted && typeof window !== "undefined" && "Notification" in window && Notification.permission === "denied") {
132→        toast.error("Notifications blocked — enable in browser settings");
133→        return;
134→      }
135→    }
136→    const next = !notificationsEnabled;
137→    setNotificationsEnabled(next);
138→    setNotificationsEnabledState(next);
139→  };
140→
141→  // Derive initial path from first workspace or fallback to "/"
142→  const initialBrowsePath = workspaces.length > 0 ? workspaces[0].cwd : "/";
143→
144→  // Connection status toasts (skip initial connection)
145→  const hasConnectedRef = useRef(false);
146→  useEffect(() => {
147→    if (connected) {
148→      if (hasConnectedRef.current) {
149→        toast.success("Reconnected");
150→      }
151→      hasConnectedRef.current = true;
152→    } else if (hasConnectedRef.current) {
153→      toast.error("Connection lost");
154→    }
155→  }, [connected]);
156→
157→  useEffect(() => {
158→    const agent = activeAgentId ? agents.get(activeAgentId) : undefined;
159→    const label = agent?.label;
160→    document.title = label ? `${label} — thos` : "thos — dashboard";
161→  }, [activeAgentId, agents]);
162→
163→  return (
164→    <TooltipProvider delayDuration={300}>
165→    <div className="relative flex h-dvh overflow-hidden">
166→      {/* Sidebar backdrop (mobile only) */}
167→      {sidebarOpen && (
168→        <div
169→          className="fixed inset-0 z-40 bg-black/50 md:hidden"
170→          onClick={() => setSidebarOpen(false)}
171→        />
172→      )}
173→
174→      {/* Sidebar drawer */}
175→      <div
176→        className={cn(
177→          "fixed inset-y-0 left-0 z-50 w-56 transition-transform duration-200 ease-in-out md:relative md:z-auto md:translate-x-0 md:transition-none",
178→          sidebarOpen ? "translate-x-0" : "-translate-x-full"
179→        )}
180→      >
181→        <AgentSidebar
182→          agents={agents}
183→          agentOrder={agentOrder}
184→          activeAgentId={activeAgentId}
185→          loading={!initialLoadDone}
186→          onSelect={(id) => {
187→            navigateToAgent(id);
188→            setSidebarOpen(false);
189→          }}
190→          onNewAgent={() => {
191→            navigateToAgent(null);
192→            setSidebarOpen(false);
193→          }}
194→          onKill={killAgent}
195→          onDelete={deleteAgent}
196→          onRename={renameAgent}
197→          onClearHistory={clearHistory}
198→          onPin={pinAgent}
199→          onIcebox={iceboxAgent}
200→          onMoveAgent={moveAgent}
201→          workspaces={workspaces}
202→          activeWorkspaceId={activeWorkspaceId}
203→          onSelectWorkspace={setActiveWorkspaceId}
204→          onRenameWorkspace={renameWorkspace}
205→          onDeleteWorkspace={deleteWorkspace}
206→          onOpenFolder={() => setFolderBrowserOpen(true)}
207→        />
208→      </div>
209→
210→      {/* Main area: world view or chat (hidden in board mode) */}
211→      <div className={cn("flex min-w-0 flex-1 flex-col", taskView === "board" && "hidden")}>
212→        {showWorld ? (
213→          <AgentWorld
214→            agents={agents}
215→            agentOrder={agentOrder}
216→            activeAgentId={activeAgentId}
217→            onSelect={(id) => {
218→              navigateToAgent(id);
219→              setShowWorld(false);
220→            }}
221→            onBack={() => setShowWorld(false)}
222→          />
223→        ) : (
224→          <Chat
225→            connected={connected}
226→            loading={!initialLoadDone || historyLoading}
227→            status={activeStatus}
228→            agentLabel={activeAgentId ? agents.get(activeAgentId)?.label : null}
229→            messages={activeMessages}
230→            rawMessages={activeRawMessages}
231→            activeModel={activeModel}
232→            selectedModel={selectedModel}
233→            onModelChange={setSelectedModel}
234→            onSendMessage={sendMessage}
235→            onSpawnAgent={(prompt, systemPrompt) => spawnAgent(prompt, selectedModel || undefined, systemPrompt)}
236→            onRespondToControl={respondToControl}
237→            onRespondToUserQuestion={respondToUserQuestion}
238→            onClearHistory={() => { if (activeAgentId) clearHistory(activeAgentId); }}
239→            showTasks={taskView !== "hidden"}
240→            onToggleTasks={() => setTaskView((v) => (v === "hidden" ? "list" : "hidden"))}
241→            showDiffs={showDiffs}
242→            onToggleDiffs={() => setShowDiffs((v) => !v)}
243→            onToggleSidebar={() => setSidebarOpen((v) => !v)}
244→            showWorld={showWorld}
245→            onToggleWorld={() => setShowWorld((v) => !v)}
246→            onOpenSettings={() => setSettingsOpen(true)}
247→            defaultSystemPrompt={defaultSystemPrompt}
248→            notificationsEnabled={notificationsEnabled}
249→            onToggleNotifications={handleToggleNotifications}
250→            notifications={notifications}
251→            onSelectNotification={(agentId, notifId) => {
252→              navigateToAgent(agentId);
253→              markNotificationRead(notifId);
254→            }}
255→            onDismissNotification={dismissNotification}
256→            onClearNotifications={clearNotifications}
257→            onTestNotification={testNotification}
258→          />
259→        )}
260→      </div>
261→
262→      {/* Task panel backdrop (mobile only) */}
263→      {taskView !== "hidden" && (
264→        <div
265→          className="fixed inset-0 z-40 bg-black/50 md:hidden"
266→          onClick={() => setTaskView("hidden")}
267→        />
268→      )}
269→
270→      {/* Task panel drawer */}
271→      {taskView !== "hidden" && (
272→        <div
273→          className={cn(
274→            "fixed inset-y-0 right-0 z-50 border-l bg-background flex flex-col min-w-0 md:relative md:z-auto",
275→            taskView === "board"
276→              ? "w-full max-w-none"
277→              : "w-80 max-w-[calc(100vw-3rem)] md:max-w-none"
278→          )}
279→        >
280→          <TaskPanel
281→            tasks={tasks}
282→            mode={taskView}
283→            onModeChange={(mode) => setTaskView(mode)}
284→            onCreateTask={createTask}
285→            onUpdateTask={updateTask}
286→            onDeleteTask={deleteTask}
287→            onDelegateTask={delegateTask}
288→            onSelectAgent={(agentId) => {
289→              navigateToAgent(agentId);
290→            }}
291→            onClose={() => setTaskView("hidden")}
292→          />
293→        </div>
294→      )}
295→
296→      {/* Diffs panel backdrop (mobile only) */}
297→      {showDiffs && (
298→        <div
299→          className="fixed inset-0 z-40 bg-black/50 md:hidden"
300→          onClick={() => setShowDiffs(false)}
301→        />
302→      )}
303→
304→      {/* Diffs panel drawer */}
305→      {showDiffs && (
306→        <div className="fixed inset-y-0 right-0 z-50 w-96 max-w-[calc(100vw-3rem)] md:max-w-none border-l bg-background flex flex-col min-w-0 md:relative md:z-auto">
307→          <DiffsPanel
308→            messages={activeMessages}
309→            onSendMessage={sendMessage}
310→            onClose={() => setShowDiffs(false)}
311→          />
312→        </div>
313→      )}
314→
315→      {/* Settings menu */}
316→      <SettingsMenu
317→        open={settingsOpen}
318→        onClose={() => setSettingsOpen(false)}
319→        notificationsEnabled={notificationsEnabled}
320→        onToggleNotifications={handleToggleNotifications}
321→        onTestNotification={testNotification}
322→        defaultPrompt={defaultSystemPrompt}
323→        onDefaultPromptChange={(value) => {
324→          setDefaultSystemPrompt(value);
325→          setDefaultPrompt(value);
326→        }}
327→      />
328→
329→      {/* Folder browser modal */}
330→      <FolderBrowser
331→        open={folderBrowserOpen}
332→        onClose={() => setFolderBrowserOpen(false)}
