  1→"use client";
  2→
  3→/**
  4→ * Main chat interface for the thos dashboard.
  5→ *
  6→ * Composes {@link StatusBar}, a scrollable message list ({@link Message}
  7→ * and {@link ControlRequest} cards), and an input bar. The submit button
  8→ * text toggles between "Spawn" (when idle/done) and "Send" (when an
  9→ * agent session is active). Auto-scrolls on new messages.
 10→ *
 11→ * A toggle in the top-right switches between the processed chat view
 12→ * and a raw JSON view of all Claude NDJSON messages.
 13→ *
 14→ * Receives all data and callbacks via props — the parent page component
 15→ * owns the WebSocket hook and orchestrates multiple agents.
 16→ */
 17→
 18→import { useMemo, useRef, useState } from "react";
 19→import { Virtuoso, type VirtuosoHandle } from "react-virtuoso";
 20→import { ArrowDown, ChevronDown, ChevronRight, ListTodo, MessageSquare, Terminal } from "lucide-react";
 21→import type { AgentStatus, ChatMessage, ClaudeMessage, NotificationItem } from "@/lib/types";
 22→import { condenseMessages } from "@/lib/condense-messages";
 23→import { StatusBar } from "./status-bar";
 24→import { AgentSummary } from "./agent-summary";
 25→import { Message } from "./message";
 26→import { ControlRequest } from "./control-request";
 27→import { UserQuestion } from "./user-question";
 28→import { CondensedToolGroup } from "./condensed-tool-group";
 29→import { SlashCommandMenu, filterCommands, type SlashCommand } from "./slash-command-menu";
 30→import { ContextUsageCard } from "./context-usage-card";
 31→import { Button } from "@/components/ui/button";
 32→
 33→export function Chat({
 34→  connected,
 35→  loading,
 36→  status,
 37→  agentLabel,
 38→  messages,
 39→  rawMessages,
 40→  activeModel,
 41→  selectedModel,
 42→  onModelChange,
 43→  onSendMessage,
 44→  onSpawnAgent,
 45→  onRespondToControl,
 46→  onRespondToUserQuestion,
 47→  onClearHistory,
 48→  showTasks,
 49→  onToggleTasks,
 50→  showDiffs,
 51→  onToggleDiffs,
 52→  onToggleSidebar,
 53→  showWorld,
 54→  onToggleWorld,
 55→  onOpenSettings,
 56→  defaultSystemPrompt,
 57→  notificationsEnabled,
 58→  onToggleNotifications,
 59→  notifications,
 60→  onSelectNotification,
 61→  onDismissNotification,
 62→  onClearNotifications,
 63→  onTestNotification,
 64→}: {
 65→  connected: boolean;
 66→  loading?: boolean;
 67→  status: AgentStatus;
 68→  agentLabel?: string | null;
 69→  messages: ChatMessage[];
 70→  rawMessages: ClaudeMessage[];
 71→  activeModel?: string | null;
 72→  selectedModel?: string;
 73→  onModelChange?: (model: string) => void;
 74→  onSendMessage: (content: string) => void;
 75→  onSpawnAgent: (prompt: string, systemPrompt?: string) => void;
 76→  onRespondToControl: (requestId: string, allow: boolean) => void;
 77→  onRespondToUserQuestion: (requestId: string, answers: Record<string, string>) => void;
 78→  onClearHistory?: () => void;
 79→  showTasks?: boolean;
 80→  onToggleTasks?: () => void;
 81→  showDiffs?: boolean;
 82→  onToggleDiffs?: () => void;
 83→  onToggleSidebar?: () => void;
 84→  showWorld?: boolean;
 85→  onToggleWorld?: () => void;
 86→  onOpenSettings?: () => void;
 87→  defaultSystemPrompt?: string;
 88→  notificationsEnabled?: boolean;
 89→  onToggleNotifications?: () => void;
 90→  notifications?: NotificationItem[];
 91→  onSelectNotification?: (agentId: string, notificationId: string) => void;
 92→  onDismissNotification?: (id: string) => void;
 93→  onClearNotifications?: () => void;
 94→  onTestNotification?: () => void;
 95→}) {
 96→  const [input, setInput] = useState("");
 97→  const [systemPrompt, setSystemPrompt] = useState("");
 98→  const [showSystemPrompt, setShowSystemPrompt] = useState(false);
 99→  const [showRaw, setShowRaw] = useState(false);
100→  const [showContext, setShowContext] = useState(false);
101→  const [showSlashMenu, setShowSlashMenu] = useState(false);
102→  const [slashQuery, setSlashQuery] = useState("");
103→  const [slashHighlight, setSlashHighlight] = useState(0);
104→  const [atBottom, setAtBottom] = useState(true);
105→  const virtuosoRef = useRef<VirtuosoHandle>(null);
106→  const inputRef = useRef<HTMLInputElement>(null);
107→
108→  const displayItems = useMemo(() => condenseMessages(messages), [messages]);
109→  const isActive = status === "connected" || status === "thinking";
110→  const isArchived = status === "done" || status === "disconnected" || status === "error";
111→
112→  function handleSubmit(e: React.FormEvent) {
113→    e.preventDefault();
114→    const trimmed = input.trim();
115→    if (!trimmed) return;
116→
117→    if (isActive) {
118→      onSendMessage(trimmed);
119→    } else {
120→      const parts = [defaultSystemPrompt?.trim(), systemPrompt.trim()].filter(Boolean);
121→      const finalSystemPrompt = parts.join("\n\n") || undefined;
122→      onSpawnAgent(trimmed, finalSystemPrompt);
123→      setSystemPrompt("");
124→      setShowSystemPrompt(false);
125→    }
126→    setInput("");
127→    setShowSlashMenu(false);
128→  }
129→
130→  function handleInputChange(e: React.ChangeEvent<HTMLInputElement>) {
131→    const value = e.target.value;
132→    setInput(value);
133→
134→    if (value.startsWith("/")) {
135→      setShowSlashMenu(true);
136→      setSlashQuery(value.slice(1));
137→      setSlashHighlight(0);
138→    } else {
139→      setShowSlashMenu(false);
140→      setSlashQuery("");
141→    }
142→  }
143→
144→  function handleKeyDown(e: React.KeyboardEvent<HTMLInputElement>) {
145→    if (!showSlashMenu) return;
146→    const filtered = filterCommands(slashQuery);
147→    if (filtered.length === 0) return;
148→
149→    if (e.key === "ArrowDown") {
150→      e.preventDefault();
151→      setSlashHighlight((i) => (i + 1) % filtered.length);
152→    } else if (e.key === "ArrowUp") {
153→      e.preventDefault();
154→      setSlashHighlight((i) => (i - 1 + filtered.length) % filtered.length);
155→    } else if (e.key === "Enter") {
156→      e.preventDefault();
157→      handleCommandSelect(filtered[slashHighlight]);
158→    } else if (e.key === "Escape") {
159→      e.preventDefault();
160→      setShowSlashMenu(false);
161→    } else if (e.key === "Tab") {
162→      e.preventDefault();
163→      setInput(`/${filtered[slashHighlight].name} `);
164→      setShowSlashMenu(false);
165→    }
166→  }
167→
168→  function handleCommandSelect(command: SlashCommand) {
169→    setShowSlashMenu(false);
170→    setSlashQuery("");
171→    setInput("");
172→
173→    if (command.clientSide) {
174→      if (command.name === "clear") {
175→        onClearHistory?.();
176→      } else if (command.name === "context") {
177→        setShowContext((v) => !v);
178→      }
179→      return;
180→    }
181→
182→    const commandText = `/${command.name}`;
183→    if (isActive) {
184→      onSendMessage(commandText);
185→    } else {
186→      onSpawnAgent(commandText);
187→    }
188→  }
189→
190→  return (
191→    <div className="flex h-full flex-col">
192→      <StatusBar
193→        connected={connected}
194→        status={status}
195→        agentLabel={agentLabel}
196→        activeModel={activeModel}
197→        selectedModel={selectedModel}
198→        onModelChange={onModelChange}
199→        showRaw={showRaw}
200→        onToggleRaw={() => setShowRaw((v) => !v)}
201→        showTasks={showTasks}
202→        onToggleTasks={onToggleTasks}
203→        showDiffs={showDiffs}
204→        onToggleDiffs={onToggleDiffs}
205→        onToggleSidebar={onToggleSidebar}
206→        showWorld={showWorld}
207→        onToggleWorld={onToggleWorld}
208→        onOpenSettings={onOpenSettings}
209→        notificationsEnabled={notificationsEnabled}
210→        onToggleNotifications={onToggleNotifications}
211→        notifications={notifications}
212→        onSelectNotification={onSelectNotification}
213→        onDismissNotification={onDismissNotification}
214→        onClearNotifications={onClearNotifications}
215→        onTestNotification={onTestNotification}
216→      />
217→
218→      <AgentSummary rawMessages={rawMessages} />
219→
220→      <div className="relative flex-1 overflow-hidden">
221→        {loading ? (
222→          <div className="flex h-full flex-col items-center justify-center gap-3">
223→            <div className="flex gap-1">
224→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse" />
225→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse [animation-delay:150ms]" />
226→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse [animation-delay:300ms]" />
227→            </div>
228→            <span className="text-xs text-muted-foreground">
229→              {connected ? "Loading messages..." : "Connecting..."}
230→            </span>
231→          </div>
232→        ) : showRaw ? (
233→          <div className="h-full overflow-y-auto p-2 md:p-4 space-y-1">
234→            {rawMessages.length === 0 ? (
235→              <div className="flex h-full items-center justify-center text-sm text-muted-foreground">
236→                No raw messages yet
237→              </div>
238→            ) : (
239→              rawMessages.map((msg, i) => (
240→                <RawMessage key={i} message={msg} index={i} />
241→              ))
242→            )}
243→          </div>
244→        ) : (
245→          <Virtuoso
246→            ref={virtuosoRef}
247→            data={displayItems}
248→            style={{ height: "100%" }}
249→            initialTopMostItemIndex={displayItems.length - 1}
250→            followOutput={(isAtBottom) => isAtBottom ? "smooth" : false}
251→            atBottomStateChange={setAtBottom}
252→            increaseViewportBy={200}
253→            itemContent={(_index, item) => (
254→              <div className="px-2 pb-2 md:px-4">
255→                {item.kind === "condensed" ? (
256→                  <CondensedToolGroup key={item.id} group={item} onSendMessage={onSendMessage} />
257→                ) : item.message.userQuestion ? (
258→                  <UserQuestion key={item.message.id} message={item.message} onRespond={onRespondToUserQuestion} />
259→                ) : item.message.controlRequest ? (
260→                  <ControlRequest key={item.message.id} message={item.message} onRespond={onRespondToControl} />
261→                ) : (
262→                  <Message key={item.message.id} message={item.message} onSendMessage={onSendMessage} />
263→                )}
264→              </div>
265→            )}
266→            components={{
267→              Header: () => <div className="h-2" />,
268→              Footer: showContext ? () => (
269→                <div className="px-2 pb-2 md:px-4">
270→                  <div className="flex flex-col gap-0.5 items-start">
271→                    <ContextUsageCard rawMessages={rawMessages} activeModel={activeModel} />
272→                  </div>
273→                </div>
274→              ) : undefined,
275→              EmptyPlaceholder: () => (
276→                <div className="flex h-full flex-col items-center justify-center gap-4 text-muted-foreground">
277→                  <Terminal className="size-10 opacity-30" />
278→                  <div className="text-center">
279→                    <p className="text-sm font-medium text-foreground/80">No agent selected</p>
280→                    <p className="mt-1 text-xs">Type a prompt below to spawn a Claude agent</p>
281→                  </div>
282→                  <div className="mt-2 grid grid-cols-2 gap-3 text-[11px]">
283→                    <div className="flex items-start gap-2 rounded-lg border p-3">
284→                      <MessageSquare className="mt-0.5 size-3.5 shrink-0 text-primary" />
285→                      <div>
286→                        <p className="font-medium text-foreground/80">Chat</p>
287→                        <p className="mt-0.5">Send prompts and review tool calls in real time</p>
288→                      </div>
289→                    </div>
290→                    <div className="flex items-start gap-2 rounded-lg border p-3">
291→                      <ListTodo className="mt-0.5 size-3.5 shrink-0 text-primary" />
292→                      <div>
293→                        <p className="font-medium text-foreground/80">Tasks</p>
294→                        <p className="mt-0.5">Track work with a kanban board and delegate to agents</p>
295→                      </div>
296→                    </div>
297→                  </div>
298→                </div>
299→              ),
300→            }}
301→          />
302→        )}
303→        {!atBottom && displayItems.length > 0 && !showRaw && !loading && (
304→          <button
305→            onClick={() => virtuosoRef.current?.scrollToIndex({ index: displayItems.length - 1, behavior: "smooth" })}
306→            className="absolute bottom-3 right-3 flex items-center gap-1 rounded-full border bg-background/90 px-3 py-1.5 text-xs text-muted-foreground shadow-md backdrop-blur transition-colors hover:text-foreground"
307→          >
308→            <ArrowDown className="size-3" />
309→            Latest
310→          </button>
311→        )}
312→      </div>
313→
314→      {isArchived && messages.length > 0 ? (
315→        <div className="border-t px-4 py-2 text-center text-xs text-muted-foreground">
316→          This session has ended
