341→                <span className="text-xs">{t.label}</span>
342→                <span className="text-[10px] text-muted-foreground ml-2">{t.desc}</span>
343→              </div>
344→            </div>
345→          ))}
346→        </div>
347→      </div>
348→
349→      <div className="border-t" />
350→
351→      {/* Test button */}
352→      <div className="flex items-center gap-2">
353→        <Button
354→          variant="outline"
355→          size="xs"
