359→            setTestResult(result);
360→            onTest?.();
361→            if (result === "sent") setTimeout(() => setTestResult(null), 3000);
362→          }}
363→        >
364→          Send Test Notification
365→        </Button>
366→        {testResult && (
367→          <span
368→            className={cn(
369→              "text-[10px]",
370→              testResult === "sent" ? "text-green-400" : "text-red-400"
371→            )}
372→          >
373→            {testResult}
374→          </span>
375→        )}
376→      </div>
377→    </div>
378→  );
379→}
380→
381→// ── Defaults Tab ─────────────────────────────────────────────────────────────
382→
383→function DefaultsTab({
384→  prompt,
385→  onPromptChange,
386→}: {
387→  prompt: string;
388→  onPromptChange: (value: string) => void;
389→}) {
390→  return (
391→    <div className="space-y-4">
392→      <div>
393→        <div className="text-xs font-medium">Default System Prompt</div>
394→        <div className="text-[10px] text-muted-foreground mt-0.5 mb-2">
395→          Appended as system instructions to every new agent spawn. Leave empty to use none.
396→        </div>
397→        <textarea
398→          value={prompt}
399→          onChange={(e) => onPromptChange(e.target.value)}
400→          placeholder="e.g. Always use TypeScript strict mode. Prefer functional patterns. Keep responses concise."
401→          rows={5}
402→          className="w-full resize-none rounded-md border bg-background px-3 py-2 text-xs outline-none focus:ring-2 focus:ring-ring"
403→        />
404→      </div>
405→
406→      <div className="border-t" />
407→
408→      <div>
409→        <div className="text-xs font-medium">Prompt Tips</div>
410→        <div className="space-y-1.5 mt-2">
411→          {[
412→            "Set coding style preferences (language, patterns, conventions)",
413→            "Define review focus areas (security, performance, readability)",
414→            "Specify project context the agent should always know",
415→            "Set behavioral guidelines (verbosity, confirmation habits)",
416→          ].map((tip) => (
417→            <div key={tip} className="flex items-start gap-2 text-[10px] text-muted-foreground">
418→              <span className="text-primary mt-0.5">*</span>
419→              <span>{tip}</span>
420→            </div>
421→          ))}
422→        </div>
423→      </div>
424→    </div>
425→  );
426→}
427→
428→// ── Display Tab ──────────────────────────────────────────────────────────────
429→
430→function DisplayTab() {
431→  return (
432→    <div className="space-y-4">
433→      <div>
434→        <div className="text-xs font-medium">Theme</div>
435→        <div className="text-[10px] text-muted-foreground mt-0.5">
436→          Dark mode is the default and only supported theme.
437→        </div>
438→      </div>
439→
440→      <div className="border-t" />
441→
442→      <div>
443→        <div className="text-xs font-medium">Message Display</div>
444→        <div className="text-[10px] text-muted-foreground mt-0.5">
445→          Use the RAW toggle in the status bar to switch between processed and raw JSON views.
446→        </div>
447→      </div>
448→
449→      <div className="border-t" />
450→
451→      <div>
452→        <div className="text-xs font-medium">Panels</div>
453→        <div className="text-[10px] text-muted-foreground mt-0.5">
454→          Toggle Tasks, Diffs, and Agent World views from the status bar icons.
455→        </div>
456→      </div>
457→    </div>
458→  );
459→}
